package com.pharmnote.study;
import org.junit.Test;
import static org.junit.Assert.*;
public class RichSummaryTest {
 @Test public void rendersHeadingsBoldTablesAndWarningColor(){String html=RichSummary.document("# ภาพรวม\n\n**ยาสำคัญ**\n\n## ข้อควรระวัง\n\n| รายการ | ข้อมูล |\n| --- | --- |\n| ยา | จาก PDF |\n");assertTrue(html.contains("<strong>ยาสำคัญ</strong>"));assertTrue(html.contains("<h2 id=\"pn-heading-1\" class=warning>ข้อควรระวัง</h2>"));assertTrue(html.contains("<div class=table-wrap><table class=table-two>"));}
 @Test public void rawHtmlAndDangerousLinksCannotBecomeActiveContent(){String html=RichSummary.body("<script>alert(1)</script>\n\n[unsafe](javascript:alert%281%29)\n\n![x](https://example.org/track.png)");assertFalse(html.contains("<script>"));assertFalse(html.contains("href=\"javascript:"));assertFalse(html.contains("<img"));}
 @Test public void acceptsOuterMarkdownFenceAndPreservesLongTail(){String longText="```markdown\n# Title\n\n"+"Long complete paragraph.\n\n".repeat(12000)+"TAIL_SENTINEL\n```";String html=RichSummary.body(longText);assertTrue(html.contains("<h1 id=\"pn-heading-0\">Title</h1>"));assertTrue(html.contains("TAIL_SENTINEL"));assertFalse(html.contains("<pre><code>"));}
 @Test public void promptRequestsWholeFileAndNoGuessedDoses(){String p=StudyPrompt.create("Breast Cancer","2026","regimen","หน้า 7");assertTrue(p.contains("ทั้งเอกสาร"));assertTrue(p.contains("Markdown"));assertTrue(p.contains("หน้า 7"));assertTrue(p.contains("ไม่เติมขนาดยา"));}
 @Test public void wideTableBecomesLabelledCardsWithoutLosingValues(){String source="| Regimen | Dose | Days | Route | Source |\n| --- | --- | --- | --- | --- |\n| A | 60 mg/m² | 1, 8, 15 | IV | PDF 75; footnote n |\n| B | AUC 5 OR AUC 1.5 | 1 OR 1, 8, 15 | IV | PDF 75 |";String html=RichSummary.body(source);assertTrue(html.contains("class=table-cards"));for(String value:new String[]{"Regimen","Dose","Days","Route","Source","60 mg/m²","1, 8, 15","IV","PDF 75; footnote n","AUC 5 OR AUC 1.5"})assertTrue("Missing original cell: "+value,html.contains(value));assertFalse(html.contains("<table>"));}
 @Test public void responsiveDocumentDoesNotRequireMinimumTableWidth(){String html=RichSummary.document("| Drug | Details |\n| --- | --- |\n| Cyclophosphamide | 600 mg/m² IV Day 1 |\n");assertFalse(html.contains("min-width:480"));assertTrue(html.contains("table-layout:fixed"));assertTrue(html.contains("600 mg/m² IV Day 1"));}

}
